const incoming = $input.first().json;
const trigger = incoming.body ?? incoming;
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
if (trigger.schemaVersion !== 1) throw new Error('DISCOVERY_TRIGGER_INVALID');
if (!uuid.test(String(trigger.runId)) || !uuid.test(String(trigger.attemptToken))) throw new Error('DISCOVERY_TRIGGER_INVALID');
const generation = Number(trigger.attemptGeneration);
if (!Number.isInteger(generation) || generation < 1) throw new Error('DISCOVERY_TRIGGER_INVALID');
const sources = Array.isArray(trigger.sources) ? trigger.sources : [];
const source = sources.find((item) => {
  if (!item || item.executionMode !== 'automatic' || !uuid.test(String(item.bindingId))) return false;
  const feedUrl = String(item.configuration && item.configuration.feedUrl || '');
  return /^https:\/\/[a-z0-9.-]+\/feed\/?$/i.test(feedUrl);
});
if (!source) throw new Error('NO_AUTOMATIC_DISCOVERY_SOURCES');
const feedUrl = String(source.configuration.feedUrl);
const feedHost = feedUrl.slice('https://'.length).split('/')[0].toLowerCase();
const permittedHosts = [feedHost];
if (feedHost.startsWith('www.')) permittedHosts.push(feedHost.slice(4));
else permittedHosts.push('www.' + feedHost);
const maxObservations = Math.min(Math.max(Number(trigger.maxObservations) || 25, 1), 25);
const listingPathPrefix = source.sourceKey === 'gulf_news_business' ? '/business/' : '';
return [{ json: { runId: trigger.runId, programmeId: trigger.programmeId, attemptToken: trigger.attemptToken, attemptGeneration: generation, sourceId: source.bindingId, sourceKey: source.sourceKey, credentialGeneration: Number(source.credentialGeneration) || 0, maxObservations: maxObservations, feedUrl: feedUrl, permittedHosts: permittedHosts, listingPathPrefix: listingPathPrefix } }];

const crypto = require('crypto');
const trigger = $('Normalize Trigger').first().json;
const items = $input.all();
const feedFailed = items.some((item) => item.json && (item.json.error || item.json.level === 'error'));
const permittedHosts = new Set(Array.isArray(trigger.permittedHosts) ? trigger.permittedHosts.map((item) => String(item).toLowerCase()) : []);
const listingPathPrefix = String(trigger.listingPathPrefix || '').toLowerCase();
function permittedUrl(raw) {
  const value = String(raw || '');
  if (!value || value !== value.trim()) return null;
  const match = /^https:\/\/([a-z0-9.-]+)(\/[^?#\\\u0000-\u0020\u007f]*)$/i.exec(value);
  if (!match || match[2].startsWith('//')) return null;
  const host = match[1].toLowerCase();
  if (!permittedHosts.has(host)) return null;
  return 'https://' + host + match[2];
}
function listingPathAllowed(url) {
  if (!listingPathPrefix) return true;
  const match = /^https:\/\/[a-z0-9.-]+(\/[^?#\\\u0000-\u0020\u007f]*)$/i.exec(url);
  return Boolean(match && match[1].toLowerCase().startsWith(listingPathPrefix));
}
function isoDate(value) {
  if (!value) return null;
  const date = new Date(String(value));
  return Number.isNaN(date.getTime()) ? null : date.toISOString();
}
function firstText(...values) {
  for (const value of values) {
    const text = String(value || "").trim();
    if (text) return text;
  }
  return "";
}
function stripHtml(value) {
  return String(value || "").replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim();
}
const observations = [];
let rejectedCount = 0;
let itemsSeen = 0;
if (!feedFailed) {
  for (const item of items) {
    itemsSeen += 1;
    const row = item.json || {};
    const url = permittedUrl(row.link || row.guid);
    if (!url) { rejectedCount += 1; continue; }
    if (!listingPathAllowed(url)) continue;
    if (observations.length >= trigger.maxObservations) continue;
    const title = String(row.title || '').trim().slice(0, 500);
    const excerpt = firstText(row.contentSnippet, stripHtml(row.content), row["content:encodedSnippet"], stripHtml(row["content:encoded"]), title).slice(0, 2000);
    const sourceItemKey = String(row.guid || url).trim().slice(0, 512);
    if (!title || !excerpt || !sourceItemKey) { rejectedCount += 1; continue; }
    const publishedAt = isoDate(row.isoDate || row.pubDate);
    observations.push({
      observationId: crypto.randomUUID(),
      sourceItemKey: sourceItemKey,
      contentHash: crypto.createHash('sha256').update(sourceItemKey + '\n' + url + '\n' + title + '\n' + excerpt, 'utf8').digest('hex'),
      sourceReference: { kind: 'public_url', url: url },
      observedAt: new Date().toISOString(),
      publishedAt: publishedAt,
      dateEvidence: { method: publishedAt ? 'feed' : 'page_metadata', precision: publishedAt ? 'day' : 'unknown' },
      kind: 'news',
      title: title,
      excerpt: excerpt,
      companyHints: []
    });
  }
}
const untrustedOnly = !feedFailed && itemsSeen > 0 && rejectedCount === itemsSeen;
const lastKey = observations.length ? observations[observations.length - 1].sourceItemKey : null;
const checkpoint = { cursor: lastKey, providerJobId: null, itemsSeen: itemsSeen, pagesSeen: feedFailed ? 0 : 1 };
const completion = feedFailed
  ? { status: 'failed', counts: { ingested: 0, duplicate: 0, quarantined: 0, rejected: 0 }, checkpoint: checkpoint, usage: [{ providerRequestId: null, units: 1, unitKind: 'request' }], error: { code: 'source_unavailable', retryable: true } }
  : untrustedOnly
    ? { status: 'failed', counts: { ingested: 0, duplicate: 0, quarantined: 0, rejected: rejectedCount }, checkpoint: checkpoint, usage: [{ providerRequestId: null, units: 1, unitKind: 'request' }], error: { code: 'contract_invalid', retryable: false } }
    : { status: 'completed', counts: { ingested: observations.filter((item) => item.companyHints.length > 0).length, duplicate: 0, quarantined: observations.filter((item) => item.companyHints.length === 0).length, rejected: rejectedCount }, checkpoint: checkpoint, usage: [{ providerRequestId: null, units: 1, unitKind: 'request' }] };
return [{ json: { trigger: trigger, observations: observations, completion: completion } }];

const crypto = require('crypto');
const mapped = $input.first().json;
