if (!/^https:\/\//i.test(callbackUrl)) throw new Error('HRMNY_OS_BASE_URL_UNAVAILABLE');
return [{ json: { hasObservations: Boolean(observation), observation: observation, completion: completion, callbackUrl: callbackUrl } }];
